toad_implementation.code_blueprint:
canvas {
  size: 960px 600px;
  fill: #121820;
  font-family: "Inter, sans-serif";
}

>deepFjord = #121820;
>mountainMist = #2D3E4F;
>glacierBlue = #A3B8C7;
>frostWhite = #E2EDF4;

rect #skyGradient {
  at: top left of canvas;
  size: 960px 380px;
  fill: #1B2633;
}

circle #polarGlow {
  at: center of canvas offset 0px -80px;
  size: 400px;
  fill: alpha(>glacierBlue, 0.25);
}

rect #mountainSilhouette {
  at: bottom left of canvas;
  size: 960px 220px;
  fill: >deepFjord;
}

text #seriesHeader {
  at: top left of canvas offset 48px 48px;
  content: "LOFOTEN // ARCTIC SOLITUDE";
  font-size: 13px;
  font-weight: 500;
  color: >glacierBlue;
}

text #telemetry {
  at: bottom left of canvas offset 48px -48px;
  content: "68°09'N  13°32'E  •  ELEVATION 842M  •  -14°C";
  font-size: 11px;
  color: >frostWhite;
}
